389	pub fn node_matrix(ctx: &Ctx, i: usize) -> [f64; 6] {
390	    let n = &ctx.nodes[i];
391	    let c = &ctx.comp[i];
392	    let t = [1.0, 0.0, 0.0, 1.0, n.x + c.translate.0, n.y + c.translate.1];
393	    if c.rotate != 0.0 {
394	        let a = c.rotate.to_radians();
395	        let r = [a.cos(), a.sin(), -a.sin(), a.cos(), 0.0, 0.0];
396	        mul(&t, &r)
397	    } else {
398	        t
399	    }
400	}
