453	// Inline CSS: the node's own declarations minus what its rules already say.
454	fn inline_style(ctx: &Ctx, i: usize, out: &mut Out, text: bool) -> Result<String, Diag> {
455	    let n = &ctx.nodes[i];
456	    let (rule_props, all) = crate::compile::cascade(&ctx.sheet, n);
457	    let mut own: Vec<(String, Value)> = Vec::new();
458	    if let Some(id) = &n.id {
459	        for (rid, ds) in &ctx.sheet.id_rules {
460	            if rid == id {
461	                for d in ds {
462	                    own.retain(|e| e.0 != d.name);
463	                    own.push((d.name.clone(), d.value.clone()));
464	                }
465	            }
466	        }
467	    }
468	    for d in &n.inline {
469	        own.retain(|e| e.0 != d.name);
470	        own.push((d.name.clone(), d.value.clone()));
471	    }
472	    let sw_all = get(&all, "stroke-width").and_then(|w| value_num(&ctx.sheet.env, w)).unwrap_or(2.0);
473	    let mut tmp = Vec::new();
474	    let own_d = css_decls(ctx, &own, &mut tmp, sw_all, text)?;
475	    let mut tmp2 = Vec::new();
476	    let sw_rule = get(&rule_props, "stroke-width").and_then(|w| value_num(&ctx.sheet.env, w)).unwrap_or(2.0);
477	    let rule_d = css_decls(ctx, &rule_props, &mut tmp2, sw_rule, text)?;
478	    let mut keep = Vec::new();
479	    let mut own_d = own_d;
480	    if text {
481	        if let Some(fam) = &ctx.comp[i].family_css {
482	            if !own_d.iter().any(|(k, _)| k == "font-family") {
483	                own_d.push(("font-family".into(), fam.clone()));
484	                let pos = |k: &str| CSS_ORDER.iter().position(|x| *x == k || (*x == "stroke-style" && k == "stroke-dasharray") || (*x == "color" && k == "fill" && false)).unwrap_or(99);
485	                own_d.sort_by_key(|(k, _)| if k == "fill" { 0 } else { pos(k) });
486	            }
487	        }
488	    }
489	    for (k, v) in own_d {
490	        if rule_d.iter().any(|(rk, rv)| rk == &k && rv == &v) {
491	            continue;
492	        }
493	        keep.push((k, v));
494	    }
495	    // stroke-style depends on the effective stroke width
496	    if get(&own, "stroke-style").is_none() && get(&own, "stroke-width").is_some() {
497	        if let Some(st) = get(&all, "stroke-style").and_then(ident_of) {
498	            if st != "solid" {
499	                if let Some(d) = dasharray(st, sw_all) {
500	                    if !rule_d.iter().any(|(rk, rv)| rk == "stroke-dasharray" && rv == &d) {
501	                        keep.push(("stroke-dasharray".into(), d));
502	                    }
503	                }
504	            }
505	        }
506	    }
507	    let mut vars = Vec::new();
508	    let _ = css_decls(ctx, &own, &mut vars, sw_all, text)?;
509	    for (k, _) in &keep {
510	        let _ = k;
511	    }
512	    for v in vars {
513	        // only vars that survive into the emitted style count
514	        if keep.iter().any(|(_, val)| val.contains(&format!("var(--lini-{})", v))) {
515	            use_var(&mut out.vars, &v);
516	        }
517	    }
518	    Ok(join_decls(&keep))
519	}
