43	pub fn line_width(ctx: &Ctx, i: usize, s: &str) -> f64 {
44	    let c = &ctx.comp[i];
45	    let w = font::text_width(c.family, c.font_weight, c.font_size, s);
46	    let n = s.chars().count();
47	    if n > 1 {
48	        w + c.letter_spacing * (n as f64 - 1.0)
49	    } else {
50	        w
51	    }
52	}
