54	// Greedy word wrap at the given width.
55	pub fn wrap(ctx: &Ctx, i: usize, text: &str, maxw: f64) -> Vec<String> {
56	    let mut out = Vec::new();
57	    for para in text.split('\n') {
58	        let words: Vec<&str> = para.split(' ').filter(|w| !w.is_empty()).collect();
59	        if words.is_empty() {
60	            out.push(String::new());
61	            continue;
62	        }
63	        let mut cur = String::new();
64	        for w in words {
65	            if cur.is_empty() {
66	                cur = w.to_string();
67	                continue;
68	            }
69	            let cand = format!("{} {}", cur, w);
70	            if line_width(ctx, i, &cand) > maxw {
71	                out.push(cur);
72	                cur = w.to_string();
73	            } else {
74	                cur = cand;
75	            }
76	        }
77	        out.push(cur);
78	    }
79	    out
80	}
