82	pub fn text_block_height(ctx: &Ctx, i: usize, nlines: usize) -> f64 {
83	    let c = &ctx.comp[i];
84	    if nlines <= 1 {
85	        c.font_size
86	    } else {
87	        nlines as f64 * 1.2 * c.font_size + (nlines as f64 - 1.0) * c.line_spacing
88	    }
89	}
