98	// The cascade for one node: type chain (base first, defaults then user
99	// rules), classes, id rules, inline. Returns (rule-level props, all props).
100	pub fn cascade(sheet: &SheetModel, n: &Node) -> (Vec<(String, Value)>, Vec<(String, Value)>) {
101	    let mut props: Vec<(String, Value)> = Vec::new();
102	    fn set(props: &mut Vec<(String, Value)>, k: &str, v: &Value) {
103	        if let Some(e) = props.iter_mut().find(|e| e.0 == k) {
104	            e.1 = v.clone();
105	        } else {
106	            props.push((k.to_string(), v.clone()));
107	        }
108	    }
109	    for t in n.chain.iter().rev() {
110	        for d in type_defaults(t) {
111	            set(&mut props, &d.name, &d.value);
112	        }
113	        if let Some(df) = sheet.define(t) {
114	            for d in &df.decls {
115	                set(&mut props, &d.name, &d.value);
116	            }
117	        }
118	        for d in sheet.type_rule(t) {
119	            set(&mut props, &d.name, &d.value);
120	        }
121	    }
122	    for c in &n.classes {
123	        if let Some(cr) = sheet.class(c) {
124	            for d in &cr.decls {
125	                set(&mut props, &d.name, &d.value);
126	            }
127	        }
128	    }
129	    let rule_level = props.clone();
130	    if let Some(id) = &n.id {
131	        for (rid, ds) in &sheet.id_rules {
132	            if rid == id {
133	                for d in ds {
134	                    set(&mut props, &d.name, &d.value);
135	                }
136	            }
137	        }
138	    }
139	    for d in &n.inline {
140	        set(&mut props, &d.name, &d.value);
141	    }
142	    (rule_level, props)
143	}
