213	// The type chain of a (possibly user-defined) type, most-derived first.
214	pub fn type_chain(sheet: &SheetModel, name: &str) -> Option<(Prim, Vec<String>)> {
215	    let mut chain = Vec::new();
216	    let mut cur = name.to_string();
217	    let mut guard = 0;
218	    loop {
219	        guard += 1;
220	        if guard > 50 {
221	            return None;
222	        }
223	        if let Some(d) = sheet.define(&cur) {
224	            chain.push(cur.clone());
225	            cur = d.base.clone();
226	            continue;
227	        }
228	        let t = types::find(&cur)?;
229	        if t.name == "text" {
230	            return None;
231	        }
232	        chain.push(cur.clone());
233	        match t.base {
234	            Some(b) => cur = b.to_string(),
235	            None => return Some((t.prim, chain)),
236	        }
237	    }
238	}
