17	pub fn transform_text(s: &str, tt: &Option<String>) -> String {
18	    match tt.as_deref() {
19	        Some("uppercase") => s.to_uppercase(),
20	        Some("lowercase") => s.to_lowercase(),
21	        Some("capitalize") => {
22	            let mut out = String::new();
23	            let mut start = true;
24	            for ch in s.chars() {
25	                if start && ch.is_alphabetic() {
26	                    out.extend(ch.to_uppercase());
27	                    start = false;
28	                } else {
29	                    out.push(ch);
30	                    if ch.is_whitespace() {
31	                        start = true;
32	                    } else {
33	                        start = false;
34	                    }
35	                }
36	            }
37	            out
38	        }
39	        _ => s.to_string(),
40	    }
41	}
42	
43	pub fn line_width(ctx: &Ctx, i: usize, s: &str) -> f64 {
44	    let c = &ctx.comp[i];
45	    let w = font::text_width(c.family, c.font_weight, c.font_size, s);
46	    let n = s.chars().count();
47	    if n > 1 {
48	        w + c.letter_spacing * (n as f64 - 1.0)
49	    } else {
50	        w
51	    }
52	}
53	
54	// Greedy word wrap at the given width.
55	pub fn wrap(ctx: &Ctx, i: usize, text: &str, maxw: f64) -> Vec<String> {
56	    let mut out = Vec::new();
57	    for para in text.split('\n') {
58	        let words: Vec<&str> = para.split(' ').filter(|w| !w.is_empty()).collect();
59	        if words.is_empty() {
60	            out.push(String::new());
61	            continue;
62	        }
63	        let mut cur = String::new();
64	        for w in words {
65	            if cur.is_empty() {
66	                cur = w.to_string();
67	                continue;
68	            }
69	            let cand = format!("{} {}", cur, w);
70	            if line_width(ctx, i, &cand) > maxw {
71	                out.push(cur);
72	                cur = w.to_string();
73	            } else {
74	                cur = cand;
75	            }
76	        }
77	        out.push(cur);
78	    }
79	    out
80	}
81	
82	pub fn text_block_height(ctx: &Ctx, i: usize, nlines: usize) -> f64 {
83	    let c = &ctx.comp[i];
84	    if nlines <= 1 {
85	        c.font_size
86	    } else {
87	        nlines as f64 * 1.2 * c.font_size + (nlines as f64 - 1.0) * c.line_spacing
88	    }
89	}
90	
91	pub fn measure_text(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
92	    let raw = ctx.nodes[i].text.clone().unwrap_or_default();
93	    let tt = ctx.comp[i].text_transform.clone();
94	    let text = transform_text(raw.trim(), &tt);
95	    let lines: Vec<String> = match avail {
96	        Some(m) if !ctx.comp[i].nowrap => wrap(ctx, i, &text, m),
97	        _ => text.split('\n').map(|s| s.to_string()).collect(),
98	    };
99	    let mut w: f64 = 0.0;
100	    for l in &lines {
101	        w = w.max(line_width(ctx, i, l));
102	    }
103	    let h = text_block_height(ctx, i, lines.len());
104	    let n = &mut ctx.nodes[i];
105	    n.lines = lines;
106	    n.w = w;
107	    n.h = h;
108	}
