166	pub fn measure_grid(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
167	    let c = ctx.comp[i].clone();
168	    let pad = c.padding;
169	    let _ = avail;
170	    let props = ctx.nodes[i].props.clone();
171	    let cols = props.get("columns").map(|v| parse_tracks(ctx, v)).unwrap_or_else(|| vec![Track::Auto]);
172	    let row_specs = props.get("rows").map(|v| parse_tracks(ctx, v)).unwrap_or_default();
173	    let ncols = cols.len().max(1);
174	    let children = ctx.nodes[i].children.clone();
175	    let mut flow = Vec::new();
176	    let mut pinned = Vec::new();
177	    for &ch in &children {
178	        if ctx.comp[ch].pin.is_some() {
179	            pinned.push(ch);
180	        } else {
181	            flow.push(ch);
182	        }
183	    }
184	    for &ch in &children {
185	        measure(ctx, ch, None);
186	    }
187	    // placement: (col, row, colspan, rowspan)
188	    let env = ctx.sheet.env.clone();
189	    let mut occupied: Vec<Vec<bool>> = Vec::new();
190	    let mut place: Vec<(usize, usize, usize, usize)> = Vec::new();
191	    let mut cur_r = 0usize;
192	    let mut cur_c = 0usize;
193	    let ensure = |occ: &mut Vec<Vec<bool>>, r: usize| {
194	        while occ.len() <= r {
195	            occ.push(vec![false; ncols]);
196	        }
197	    };
198	    for &ch in &flow {
199	        let p = &ctx.nodes[ch].props;
200	        let span: Vec<f64> = p.get("span").map(|v| crate::style::value_nums(&env, v)).unwrap_or_default();
201	        let cs = span.first().map(|x| *x as usize).unwrap_or(1).max(1).min(ncols);
202	        let rs = span.get(1).map(|x| *x as usize).unwrap_or(1).max(1);
203	        if let Some(cell) = p.get("cell").map(|v| crate::style::value_nums(&env, v)) {
204	            if cell.len() >= 2 {
205	                let cc = (cell[0] as usize).max(1) - 1;
206	                let rr = (cell[1] as usize).max(1) - 1;
207	                ensure(&mut occupied, rr + rs - 1);
208	                for r in rr..rr + rs {
209	                    for k in cc..(cc + cs).min(ncols) {
210	                        occupied[r][k] = true;
211	                    }
212	                }
213	                place.push((cc, rr, cs, rs));
214	                continue;
215	            }
216	        }
217	        loop {
218	            ensure(&mut occupied, cur_r + rs - 1);
219	            if cur_c + cs > ncols {
220	                cur_c = 0;
221	                cur_r += 1;
222	                continue;
223	            }
224	            let mut free = true;
225	            for r in cur_r..cur_r + rs {
226	                ensure(&mut occupied, r);
227	                for k in cur_c..cur_c + cs {
228	                    if occupied[r][k] {
229	                        free = false;
230	                    }
231	                }
232	            }
233	            if free {
234	                break;
235	            }
236	            cur_c += 1;
237	        }
238	        for r in cur_r..cur_r + rs {
239	            for k in cur_c..cur_c + cs {
240	                occupied[r][k] = true;
241	            }
242	        }
243	        place.push((cur_c, cur_r, cs, rs));
244	        cur_c += cs;
245	    }
246	    let nrows = occupied.len();
247	    let (gr, gc) = c.gap;
248	    let mut colw: Vec<f64> = vec![0.0; ncols];
249	    let mut rowh: Vec<f64> = vec![0.0; nrows];
250	    let col_fixed: Vec<Option<f64>> = (0..ncols).map(|k| match cols.get(k) { Some(Track::Fixed(x)) => Some(*x), _ => None }).collect();
251	    let row_fixed: Vec<Option<f64>> = (0..nrows).map(|k| match row_specs.get(k) { Some(Track::Fixed(x)) => Some(*x), _ => None }).collect();
252	    for k in 0..ncols {
253	        if let Some(x) = col_fixed[k] {
254	            colw[k] = x;
255	        }
256	    }
257	    for k in 0..nrows {
258	        if let Some(x) = row_fixed[k] {
259	            rowh[k] = x;
260	        }
261	    }
262	    let sizes: Vec<(f64, f64)> = flow.iter().map(|&ch| outer(ctx, ch)).collect();
263	    for (idx, &(cc, rr, cs, rs)) in place.iter().enumerate() {
264	        let (w, h) = sizes[idx];
265	        if cs == 1 && col_fixed[cc].is_none() {
266	            colw[cc] = colw[cc].max(w);
267	        }
268	        if rs == 1 && row_fixed[rr].is_none() {
269	            rowh[rr] = rowh[rr].max(h);
270	        }
271	    }
272	    for (idx, &(cc, rr, cs, rs)) in place.iter().enumerate() {
273	        let (w, h) = sizes[idx];
274	        if cs > 1 {
275	            let cur: f64 = colw[cc..cc + cs].iter().sum::<f64>() + gc * (cs as f64 - 1.0);
276	            if w > cur {
277	                let autos: Vec<usize> = (cc..cc + cs).filter(|k| col_fixed[*k].is_none()).collect();
278	                if !autos.is_empty() {
279	                    let extra = (w - cur) / autos.len() as f64;
280	                    for k in autos {
281	                        colw[k] += extra;
282	                    }
283	                }
284	            }
285	        }
286	        if rs > 1 {
287	            let cur: f64 = rowh[rr..rr + rs].iter().sum::<f64>() + gr * (rs as f64 - 1.0);
288	            if h > cur {
289	                let autos: Vec<usize> = (rr..rr + rs).filter(|k| row_fixed[*k].is_none()).collect();
290	                if !autos.is_empty() {
291	                    let extra = (h - cur) / autos.len() as f64;
292	                    for k in autos {
293	                        rowh[k] += extra;
294	                    }
295	                }
296	            }
297	        }
298	    }
299	    let cw: f64 = colw.iter().sum::<f64>() + gc * (ncols as f64 - 1.0).max(0.0);
300	    let chh: f64 = rowh.iter().sum::<f64>() + gr * (nrows as f64 - 1.0).max(0.0);
301	    let mut w = cw + pad[1] + pad[3];
302	    let mut h = chh + pad[0] + pad[2];
303	    if let Some(fw) = c.width {
304	        w = w.max(fw);
305	    }
306	    if let Some(fh) = c.height {
307	        h = h.max(fh);
308	    }
309	    ctx.nodes[i].w = w;
310	    ctx.nodes[i].h = h;
311	    let x0 = -w / 2.0 + pad[3] + (w - pad[1] - pad[3] - cw) / 2.0;
312	    let y0 = -h / 2.0 + pad[0] + (h - pad[0] - pad[2] - chh) / 2.0;
313	    let mut colx = vec![0.0; ncols];
314	    let mut acc = x0;
315	    for k in 0..ncols {
316	        colx[k] = acc;
317	        acc += colw[k] + gc;
318	    }
319	    let mut rowy = vec![0.0; nrows];
320	    let mut acc = y0;
321	    for k in 0..nrows {
322	        rowy[k] = acc;
323	        acc += rowh[k] + gr;
324	    }
325	    if ctx.nodes[i].props.contains_key("gap-fill") {
326	        let mut g = Vec::new();
327	        if gc > 0.0 {
328	            for k in 0..ncols.saturating_sub(1) {
329	                g.push((colx[k] + colw[k], -h / 2.0, gc, h));
330	            }
331	        }
332	        if gr > 0.0 {
333	            for k in 0..nrows.saturating_sub(1) {
334	                g.push((-w / 2.0, rowy[k] + rowh[k], w, gr));
335	            }
336	        }
337	        ctx.nodes[i].gutters = g;
338	    }
339	    for (idx, &ch) in flow.iter().enumerate() {
340	        let (cc, rr, cs, rs) = place[idx];
341	        let (ow, oh) = sizes[idx];
342	        let cx0 = colx[cc];
343	        let cwid: f64 = colw[cc..cc + cs].iter().sum::<f64>() + gc * (cs as f64 - 1.0);
344	        let ry0 = rowy[rr];
345	        let rhei: f64 = rowh[rr..(rr + rs).min(nrows)].iter().sum::<f64>() + gr * (rs as f64 - 1.0);
346	        let x = match c.align {
347	            Align::Start => cx0 + ow / 2.0,
348	            Align::End => cx0 + cwid - ow / 2.0,
349	            _ => cx0 + cwid / 2.0,
350	        };
351	        let y = match c.justify {
352	            Align::Start => ry0 + oh / 2.0,
353	            Align::End => ry0 + rhei - oh / 2.0,
354	            _ => ry0 + rhei / 2.0,
355	        };
356	        ctx.nodes[ch].x = x;
357	        ctx.nodes[ch].y = y;
358	    }
359	    for &p in &pinned {
360	        place_pinned(ctx, i, p);
361	    }
362	}
