256	impl<'a> Builder<'a> {
257	    pub fn new(sheet: &'a SheetModel, src: &'a str) -> Self {
258	        Builder { sheet, src, nodes: vec![], links: vec![], pending_links: vec![], warnings: vec![], ids: HashMap::new(), cap_counter: 0, stmt_counter: 0 }
259	    }
260	
261	    // The id scope children of `p` live in: `p` itself when it has an id, else p's scope.
262	    pub fn child_scope(&self, p: usize) -> usize {
263	        if p == 0 || self.nodes[p].id.is_some() {
264	            p
265	        } else {
266	            self.nodes[p].scope
267	        }
268	    }
269	
270	    pub fn add(&mut self, mut n: Node, parent: Option<usize>) -> usize {
271	        n.parent = parent;
272	        if let Some(p) = parent {
273	            n.scope = self.child_scope(p);
274	        }
275	        let i = self.nodes.len();
276	        self.nodes.push(n);
277	        if let Some(p) = parent {
278	            self.nodes[p].children.push(i);
279	        }
280	        i
281	    }
282	
283	    pub fn text_node(&mut self, text: &str, classes: &[String], style: Option<&Vec<Decl>>, span: Span, parent: usize) -> usize {
284	        let mut n = Node::new(Prim::Text, vec![], span);
285	        n.text = Some(text.to_string());
286	        n.classes = classes.to_vec();
287	        if let Some(s) = style {
288	            n.inline = s.clone();
289	        }
290	        self.add(n, Some(parent))
291	    }
292	
293	    pub fn build_stmts(&mut self, stmts: &[Stmt], parent: usize) -> Result<(), Diag> {
294	        for s in stmts {
295	            match s {
296	                Stmt::Node(ns) => {
297	                    self.build_node(ns, parent)?;
298	                }
299	                Stmt::Text(t) => {
300	                    self.check_classes(&t.classes, t.span)?;
301	                    self.text_node(&t.text, &t.classes, t.style.as_ref(), t.span, parent);
302	                }
303	                Stmt::Link(l) => {
304	                    // capsule endpoints are declared in statement order
305	                    let idx = self.stmt_counter;
306	                    self.stmt_counter += 1;
307	                    let mut l2 = l.clone();
308	                    for g in l2.groups.iter_mut() {
309	                        for ep in g.iter_mut() {
310	                            if let Endpoint::Node(ns) = ep {
311	                                let id = match &ns.id {
312	                                    Some(id) => id.clone(),
313	                                    None => {
314	                                        self.cap_counter += 1;
315	                                        format!("lini-cap-{}", self.cap_counter)
316	                                    }
317	                                };
318	                                let mut ns2 = (**ns).clone();
319	                                ns2.id = Some(id.clone());
320	                                let ni = self.build_node(&ns2, parent)?;
321	                                if ns.id.is_none() {
322	                                    self.nodes[ni].auto = false;
323	                                }
324	                                *ep = Endpoint::Path(PathRef { parts: vec![id], index: None, anchor: None, span: ns.span });
325	                            }
326	                        }
327	                    }
328	                    self.pending_links.push((parent, l2, idx));
329	                }
330	            }
331	        }
332	        Ok(())
333	    }
334	
335	    pub fn check_classes(&mut self, classes: &[String], span: Span) -> Result<(), Diag> {
336	        for c in classes {
337	            if self.sheet.class(c).is_none() {
338	                return Err(Diag::error("unknown-class", &format!("unknown class '.{}'", c), span));
339	            }
340	        }
341	        Ok(())
342	    }
343	
344	    pub fn build_node(&mut self, ns: &NodeStmt, parent: usize) -> Result<usize, Diag> {
345	        let tname = match &ns.type_name {
346	            Some(t) => t.clone(),
347	            None => "box".to_string(),
348	        };
349	        if tname == "link" {
350	            return Err(Diag::error("resolve", "links are drawn by operators, not the '|link|' type", ns.head_span));
351	        }
352	        let (prim, chain) = match type_chain(self.sheet, &tname) {
353	            Some(x) => x,
354	            None => return Err(unknown_type(&tname, ns.span)),
355	        };
356	        self.check_classes(&ns.classes, ns.span)?;
357	        let mut n = Node::new(prim, chain.clone(), ns.span);
358	        n.id = ns.id.clone();
359	        n.classes = ns.classes.clone();
360	        if let Some(st) = &ns.style {
361	            n.inline = st.clone();
362	        }
363	        let scope = self.child_scope(parent);
364	        if let Some(id) = &ns.id {
365	            if let Some(&prev) = self.ids.get(&(scope, id.clone())) {
366	                let (pl, pc) = crate::diag::line_col(self.src, self.nodes[prev].span.start);
367	                return Err(Diag::error(
368	                    "duplicate-id",
369	                    &format!("duplicate id '{}' (previously at {}:{})", id, pl, pc),
370	                    ns.span,
371	                ));
372	            }
373	        }
374	        let i = self.add(n, Some(parent));
375	        if let Some(id) = &ns.id {
376	            self.ids.insert((scope, id.clone()), i);
377	        }
378	        // the label
379	        let is_group = chain.iter().any(|c| c == "group") && !chain.iter().any(|c| c == "table");
380	        if let Some((label, lspan)) = &ns.label {
381	            if is_group {
382	                let cchain = vec!["caption".to_string(), "block".to_string()];
383	                let mut cn = Node::new(Prim::Block, cchain, *lspan);
384	                cn.span = *lspan;
385	                let ci = self.add(cn, Some(i));
386	                self.text_node(label, &[], None, *lspan, ci);
387	            } else {
388	                match prim {
389	                    Prim::Block | Prim::Oval | Prim::Hex | Prim::Slant | Prim::Cyl | Prim::Diamond => {
390	                        self.text_node(label, &[], None, *lspan, i);
391	                    }
392	                    _ => {}
393	                }
394	            }
395	        }
396	        // a define's body is materialised per instance
397	        for t in chain.iter().rev() {
398	            if let Some(d) = self.sheet.define(t) {
399	                if let Some(body) = d.body.clone() {
400	                    self.build_stmts(&body, i)?;
401	                }
402	            }
403	        }
404	        if let Some(ch) = &ns.children {
405	            self.build_stmts(ch, i)?;
406	        }
407	        Ok(i)
408	    }
409	}
