411	impl<'a> Builder<'a> {
412	    // Dotted id path of a node from the root ("g.c").
413	    pub fn path_of(&self, i: usize) -> String {
414	        let mut parts = Vec::new();
415	        let mut cur = i;
416	        loop {
417	            if let Some(id) = &self.nodes[cur].id {
418	                parts.push(id.clone());
419	            }
420	            if cur == 0 {
421	                break;
422	            }
423	            let sc = self.nodes[cur].scope;
424	            if sc == cur {
425	                break;
426	            }
427	            cur = sc;
428	        }
429	        parts.reverse();
430	        parts.join(".")
431	    }
432	
433	    fn scope_name(&self, scope: usize) -> String {
434	        if scope == 0 {
435	            "scene root".to_string()
436	        } else {
437	            self.path_of(scope)
438	        }
439	    }
440	
441	    pub fn lookup(&self, scope: usize, parts: &[String]) -> Option<usize> {
442	        let mut cur = scope;
443	        for p in parts {
444	            cur = *self.ids.get(&(cur, p.clone()))?;
445	        }
446	        Some(cur)
447	    }
448	
449	    // First node with this id anywhere below `scope` (depth-first, document order).
450	    fn find_deep(&self, scope: usize, id: &str) -> Option<usize> {
451	        let mut stack: Vec<usize> = self.nodes[scope].children.iter().rev().cloned().collect();
452	        while let Some(n) = stack.pop() {
453	            if self.nodes[n].id.as_deref() == Some(id) && self.nodes[n].scope != scope {
454	                return Some(n);
455	            }
456	            for &c in self.nodes[n].children.iter().rev() {
457	                stack.push(c);
458	            }
459	        }
460	        None
461	    }
462	
463	    // Resolve one endpoint, auto-creating a bare name as |box#name| "name".
464	    fn endpoint(&mut self, container: usize, p: &PathRef) -> Result<usize, Diag> {
465	        let scope = self.child_scope(container);
466	        if let Some(n) = self.lookup(scope, &p.parts) {
467	            return Ok(n);
468	        }
469	        if p.parts.len() > 1 {
470	            let msg = if scope == 0 {
471	                format!("link endpoint '{}' not found at scene root", p.parts.join("."))
472	            } else {
473	                format!("link endpoint '{}' not found in '{}'", p.parts.join("."), self.path_of(scope))
474	            };
475	            return Err(Diag::error("unknown-endpoint", &msg, p.span));
476	        }
477	        let name = p.parts[0].clone();
478	        if let Some(other) = self.find_deep(scope, &name) {
479	            let msg = format!(
480	                "endpoint '{}' auto-created at {} — a node '{}' also exists at '{}'",
481	                name,
482	                self.scope_name(scope),
483	                name,
484	                self.path_of(other)
485	            );
486	            self.warnings.push(Diag::warning("validate", &msg, p.span));
487	        }
488	        let chain = vec!["box".to_string(), "block".to_string()];
489	        let mut n = Node::new(Prim::Block, chain, p.span);
490	        n.id = Some(name.clone());
491	        n.auto = true;
492	        let i = self.add(n, Some(container));
493	        self.ids.insert((scope, name.clone()), i);
494	        self.text_node(&name, &[], None, p.span, i);
495	        Ok(i)
496	    }
497	
498	    pub fn resolve_links(&mut self) -> Result<(), Diag> {
499	        let pending = std::mem::take(&mut self.pending_links);
500	        for (container, l, idx) in pending {
501	            for c in &l.classes {
502	                if self.sheet.class(c).is_none() {
503	                    return Err(Diag::error("unknown-class", &format!("unknown class '.{}'", c), l.span));
504	                }
505	            }
506	            let mut groups: Vec<Vec<(usize, Option<String>, Option<u32>)>> = Vec::new();
507	            for g in &l.groups {
508	                let mut v = Vec::new();
509	                for ep in g {
510	                    match ep {
511	                        Endpoint::Path(p) => {
512	                            let n = self.endpoint(container, p)?;
513	                            v.push((n, p.anchor.clone(), p.index));
514	                        }
515	                        Endpoint::Node(_) | Endpoint::Text(..) => {}
516	                    }
517	                }
518	                groups.push(v);
519	            }
520	            if groups.len() < 2 {
521	                return Err(Diag::error("chain-too-short", "link requires at least two endpoints", l.span));
522	            }
523	            for k in 0..groups.len() - 1 {
524	                let op = l.ops.get(k).map(|o| o.0.clone()).unwrap_or_default();
525	                for a in &groups[k] {
526	                    for b in &groups[k + 1] {
527	                        self.links.push(Link {
528	                            from: a.0,
529	                            to: b.0,
530	                            op: op.clone(),
531	                            label: l.label.as_ref().map(|x| x.0.clone()),
532	                            labels: l.labels.clone().unwrap_or_default(),
533	                            classes: l.classes.clone(),
534	                            style: l.style.clone().unwrap_or_default(),
535	                            from_anchor: a.1.clone(),
536	                            to_anchor: b.1.clone(),
537	                            from_index: a.2,
538	                            to_index: b.2,
539	                            span: l.span,
540	                            stmt_index: idx,
541	                            container,
542	                        });
543	                    }
544	                }
545	            }
546	        }
547	        Ok(())
548	    }
549	}
