#!/usr/bin/env python3
# Icon-name discovery against the original binary (black-box: compile snippets, read errors).
import subprocess, sys, re, os, json
from concurrent.futures import ThreadPoolExecutor

ORIG = '/workspace/executable'
D = '/tmp/icon/disc'
VALID = os.path.join(D, 'valid.txt')
PROBED = os.path.join(D, 'probed.txt')

def check(name):
    src = '|icon| { symbol: "%s" }' % name
    r = subprocess.run([ORIG, '-'], input=src.encode(), capture_output=True)
    if r.returncode == 0:
        return name, 'ok', []
    e = r.stderr.decode()
    m = re.search(r"unknown icon '.*?'(?:; did you mean (.*)\?)?$", e.strip())
    if not m:
        return name, 'other', [e.strip()]
    sugg = re.findall(r"'([^']*)'", m.group(1)) if m.group(1) else []
    return name, 'bad', sugg

def load(p):
    if os.path.exists(p):
        return set(open(p).read().split())
    return set()

valid = load(VALID)
probed = load(PROBED)

def save():
    open(VALID, 'w').write('\n'.join(sorted(valid)) + '\n')
    open(PROBED, 'w').write('\n'.join(sorted(probed)) + '\n')

def run(names, label=''):
    names = [n for n in dict.fromkeys(names) if n not in probed and n not in valid]
    new = set()
    with ThreadPoolExecutor(32) as ex:
        for name, st, sugg in ex.map(check, names, chunksize=64):
            probed.add(name)
            if st == 'ok':
                if name not in valid:
                    valid.add(name); new.add(name)
            elif st == 'bad':
                for s in sugg:
                    if s not in valid:
                        valid.add(s); new.add(s)
            else:
                print('OTHER', name, sugg, file=sys.stderr)
    save()
    print('%s probes=%d new=%d valid=%d' % (label, len(names), len(new), len(valid)), file=sys.stderr)
    return new

ALPHA = 'abcdefghijklmnopqrstuvwxyz0123456789-'

def neigh1(v):
    out = set()
    for i in range(len(v)):
        out.add(v[:i] + v[i+1:])
        for c in ALPHA:
            out.add(v[:i] + c + v[i+1:])
    for i in range(len(v) + 1):
        for c in ALPHA:
            out.add(v[:i] + c + v[i:])
    out.discard(v)
    return out

if __name__ == '__main__':
    mode = sys.argv[1]
    if mode == 'seeds':
        names = []
        for f in sys.argv[2:]:
            names += open(f).read().split()
        run(names, 'seeds')
    elif mode == 'neigh':
        # expand distance-1 neighbourhoods of every valid name not yet expanded
        done = load(os.path.join(D, 'expanded.txt'))
        while True:
            todo = sorted(valid - done)
            if not todo:
                break
            probes = set()
            for v in todo:
                probes |= neigh1(v)
            run(sorted(probes), 'neigh(%d names)' % len(todo))
            done |= set(todo)
            open(os.path.join(D, 'expanded.txt'), 'w').write('\n'.join(sorted(done)) + '\n')
    elif mode == 'list':
        names = sys.argv[2:]
        run(names, 'list')

