#!/usr/bin/env python3
# Capture icon artwork + bbox data from the original binary (black-box: compile and read SVG output).
import subprocess, sys, re, json
from concurrent.futures import ThreadPoolExecutor

ORIG = '/workspace/executable'
names = open('/tmp/icon/disc/valid.txt').read().split()
if len(sys.argv) > 1:
    names = sys.argv[1:]

def run(src):
    r = subprocess.run([ORIG, '-'], input=src.encode(), capture_output=True)
    if r.returncode != 0:
        raise Exception(r.stderr.decode())
    return r.stdout.decode()

def node_blocks(out):
    # split into per-node blocks keyed by data-id
    res = {}
    parts = re.split(r'\n    <g class="lini-node lini-icon" data-id="(i\d+)"[^>]*>\n', out)
    for k in range(1, len(parts), 2):
        body = parts[k + 1]
        end = body.find('\n    </g>\n')
        res[parts[k]] = body[:end + 1]
    return res

def parse_art(block):
    lines = block.split('\n')
    head = lines[0].strip()
    m = re.match(r'<g transform="scale\(([^)]*)\) translate\(([^ ]*) ([^)]*)\)">$', head)
    assert m, head
    groups = []
    cur = None
    for l in lines[1:]:
        s = l.strip()
        if not s:
            continue
        if l.startswith('        <g ') and s.endswith('>'):
            cur = (s, [])
            groups.append(cur)
        elif l.startswith('        </g>'):
            cur = None
        elif l.startswith('      </g>'):
            break
        else:
            assert cur is not None and l.startswith('          <'), repr(l)
            cur[1].append(s)
    return m.group(1), m.group(2), m.group(3), groups

def batch(chunk):
    out = {}
    src = '{ direction: column; }\n' + '\n'.join('|icon#i%d| { symbol: "%s"; }' % (k, n) for k, n in chunk)
    o = run(src)
    blocks = node_blocks(o)
    src2 = '{ direction: column; }\n' + '\n'.join('|icon#i%d| { symbol: "%s"; fit: stretch; width: 1000000000000; }' % (k, n) for k, n in chunk)
    o2 = run(src2)
    blocks2 = node_blocks(o2)
    for k, n in chunk:
        sc, tx, ty, groups = parse_art(blocks['i%d' % k])
        assert sc == '0.125' and tx == '-128' and ty == '-128', (n, sc, tx, ty)
        head2 = blocks2['i%d' % k].split('\n')[0].strip()
        m = re.match(r'<g transform="scale\(([^ ]*) ([^)]*)\) translate\(([^ ]*) ([^)]*)\)">$', head2)
        assert m, (n, head2)
        out[n] = {'groups': groups, 'sx': m.group(1), 'sy': m.group(2), 'tx': m.group(3), 'ty': m.group(4)}
    return out

items = list(enumerate(names))
chunks = [items[i:i + 50] for i in range(0, len(items), 50)]
data = {}
with ThreadPoolExecutor(16) as ex:
    for r in ex.map(batch, chunks):
        data.update(r)
json.dump(data, open('/tmp/icon/disc/art.json', 'w'), indent=0)
print(len(data))

