// Built-in icons: `|icon|` and its larger preset `|sign|`.
//
// The artwork table (data/icons.txt) holds every symbol on a 256×256 canvas in
// three layers: the duotone body (painted with the node's fill), the line work
// (stroked with the node's stroke, counter-scaled so the stroke width stays
// even at any size) and dots (filled with the stroke colour). Each entry also
// carries its artwork bounding box, which `fit: contain | cover | stretch`
// frame to the node; `fit: auto` maps the whole 256 canvas.
//
// An icon is a square: its side is the larger of its laid-out width and height
// (children flow inside it like a block's, gap 0 by default).

use crate::ast::{Decl, Term};
use crate::compile::{get, Ctx};
use crate::diag::Diag;
use crate::scene::{Node, SheetModel};
use crate::style::{color_css, ident_of, single_term};
use crate::types::Prim;
use crate::util::{f4, levenshtein};
use std::sync::OnceLock;

pub struct IconDef {
    pub name: &'static str,
    // translate that centres the artwork bbox, as printed (`-128`, `-128.028`)
    pub tx: &'static str,
    pub ty: &'static str,
    // artwork bbox size
    pub bw: f64,
    pub bh: f64,
    pub body: Vec<&'static str>,
    pub line: Vec<&'static str>,
    pub dots: Vec<&'static str>,
}

static DATA: &str = include_str!("../data/icons.txt");
static TABLE: OnceLock<Vec<IconDef>> = OnceLock::new();

// Every icon, sorted by name.
pub fn table() -> &'static [IconDef] {
    TABLE.get_or_init(|| {
        let mut out: Vec<IconDef> = Vec::new();
        for line in DATA.lines() {
            if line.starts_with('#') || line.is_empty() {
                continue;
            }
            if let Some(head) = line.strip_prefix('@') {
                let f: Vec<&'static str> = head.split(' ').collect();
                out.push(IconDef {
                    name: f[0],
                    tx: f[1],
                    ty: f[2],
                    bw: f[3].parse().unwrap_or(256.0),
                    bh: f[4].parse().unwrap_or(256.0),
                    body: vec![],
                    line: vec![],
                    dots: vec![],
                });
                continue;
            }
            let d = match out.last_mut() {
                Some(d) => d,
                None => continue,
            };
            let (kind, el) = line.split_at(2);
            match kind {
                "b " => d.body.push(el),
                "l " => d.line.push(el),
                "d " => d.dots.push(el),
                _ => {}
            }
        }
        out.sort_by(|a, b| a.name.cmp(b.name));
        out
    })
}

pub fn find(name: &str) -> Option<&'static IconDef> {
    let t = table();
    t.binary_search_by(|d| d.name.cmp(name)).ok().map(|k| &t[k])
}

// Up to three names within two edits, nearest first, then by name.
pub fn suggestions(name: &str) -> Vec<&'static str> {
    let mut c: Vec<(usize, &'static str)> = table()
        .iter()
        .filter_map(|d| {
            let k = levenshtein(name, d.name);
            if k <= 2 {
                Some((k, d.name))
            } else {
                None
            }
        })
        .collect();
    c.sort();
    c.into_iter().take(3).map(|(_, n)| n).collect()
}

pub fn unknown_icon(name: &str) -> String {
    let s = suggestions(name);
    if s.is_empty() {
        format!("unknown icon '{}'", name)
    } else {
        let q: Vec<String> = s.iter().map(|n| format!("'{}'", n)).collect();
        format!("unknown icon '{}'; did you mean {}?", name, q.join(", "))
    }
}

// The declaration that wins the cascade for `name` (user-written decls only:
// type rules and defines base-first, classes, id rules, inline).
pub fn winning_decl<'a>(sheet: &'a SheetModel, n: &'a Node, name: &str) -> Option<&'a Decl> {
    let mut found: Option<&Decl> = None;
    for t in n.chain.iter().rev() {
        if let Some(df) = sheet.define(t) {
            for d in &df.decls {
                if d.name == name {
                    found = Some(d);
                }
            }
        }
        for d in sheet.type_rule(t) {
            if d.name == name {
                found = Some(d);
            }
        }
    }
    for c in &n.classes {
        if let Some(cr) = sheet.class(c) {
            for d in &cr.decls {
                if d.name == name {
                    found = Some(d);
                }
            }
        }
    }
    if let Some(id) = &n.id {
        for (rid, ds) in &sheet.id_rules {
            if rid == id {
                for d in ds {
                    if d.name == name {
                        found = Some(d);
                    }
                }
            }
        }
    }
    for d in &n.inline {
        if d.name == name {
            found = Some(d);
        }
    }
    found
}

pub const FITS: &[&str] = &["auto", "contain", "cover", "stretch"];

fn check_fit(props: &[(String, crate::ast::Value)], n: &Node) -> Result<(), Diag> {
    if let Some(v) = get(props, "fit") {
        if !ident_of(v).map(|s| FITS.contains(&s)).unwrap_or(false) {
            return Err(Diag::error("resolve", "'fit' must be auto, contain, cover, or stretch", n.span));
        }
    }
    Ok(())
}

// Resolve-time checks for every icon and image, in document order: 'fit',
// the icon symbol, the image source (read here, so a missing file fails
// before layout).
pub fn validate(nodes: &[Node], sheet: &SheetModel, file: &str, opts: &crate::Options) -> Result<(), Diag> {
    for n in nodes {
        if n.prim != Prim::Icon && n.prim != Prim::Image {
            continue;
        }
        let (_, props) = crate::compile::cascade(sheet, n);
        check_fit(&props, n)?;
        if n.prim == Prim::Icon {
            check_symbol(sheet, n, &props)?;
        } else {
            crate::image::check_src(sheet, n, file, opts)?;
        }
    }
    Ok(())
}

fn check_symbol(sheet: &SheetModel, n: &Node, props: &[(String, crate::ast::Value)]) -> Result<(), Diag> {
    let sym = get(props, "symbol");
    let name = match (&n.text, sym) {
        (Some(_), Some(_)) => {
            return Err(Diag::error("resolve", "an icon's symbol is its label or 'symbol:', not both", n.span));
        }
        (Some(label), None) => label.clone(),
        (None, Some(v)) => {
            if v.groups.len() > 1 {
                let span = winning_decl(sheet, n, "symbol").map(|d| d.span).unwrap_or(v.span);
                return Err(Diag::error("malformed-value", "'symbol' takes one value, not a comma list", span));
            }
            match single_term(v) {
                Some(Term::Ident(s, _)) | Some(Term::Str(s, _)) => s.clone(),
                _ => {
                    return Err(Diag::error("resolve", "'symbol' must be an icon name, e.g. { symbol: heart }", n.span));
                }
            }
        }
        (None, None) => {
            return Err(Diag::error("resolve", "'|icon|' needs a 'symbol' (e.g. { symbol: heart })", n.span));
        }
    };
    if find(&name).is_none() {
        return Err(Diag::error("resolve", &unknown_icon(&name), n.span));
    }
    Ok(())
}

// The symbol name of an icon node (its label, else `symbol:`).
pub fn symbol_of(ctx: &Ctx, i: usize) -> Option<String> {
    let n = &ctx.nodes[i];
    if let Some(l) = &n.text {
        return Some(l.clone());
    }
    match ctx.nodes[i].props.get("symbol").and_then(single_term) {
        Some(Term::Ident(s, _)) | Some(Term::Str(s, _)) => Some(s.clone()),
        _ => None,
    }
}

pub fn fit_of(ctx: &Ctx, i: usize) -> &'static str {
    let f = ctx.nodes[i].props.get("fit").and_then(ident_of).unwrap_or("auto");
    FITS.iter().find(|x| **x == f).copied().unwrap_or("auto")
}

// Icons and images lay their children out like a block (gap 0 unless set);
// an icon then squares itself, an image without children is exactly its
// width × height.
pub fn measure(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
    let prim = ctx.nodes[i].prim;
    if !ctx.nodes[i].props.contains_key("gap") {
        ctx.comp[i].gap = (0.0, 0.0);
    }
    if prim == Prim::Image && ctx.nodes[i].children.is_empty() {
        ctx.nodes[i].w = ctx.comp[i].width.unwrap_or(0.0);
        ctx.nodes[i].h = ctx.comp[i].height.unwrap_or(0.0);
        return;
    }
    crate::layout::measure_flow(ctx, i, avail);
    if prim == Prim::Icon {
        let s = ctx.nodes[i].w.max(ctx.nodes[i].h);
        ctx.nodes[i].w = s;
        ctx.nodes[i].h = s;
    }
}

fn paint(ctx: &Ctx, i: usize, k: &str) -> String {
    match ctx.nodes[i].props.get(k) {
        Some(v) => match single_term(v) {
            Some(t) => {
                let mut tmp = Vec::new();
                color_css(t, &mut tmp, v.span).unwrap_or_else(|_| "none".to_string())
            }
            None => "none".to_string(),
        },
        None => "none".to_string(),
    }
}

// The artwork group (unindented lines, nested lines indented by two).
pub fn shape_lines(ctx: &Ctx, i: usize) -> Vec<String> {
    let def = match symbol_of(ctx, i).and_then(|s| find(&s)) {
        Some(d) => d,
        None => return vec![],
    };
    let side = ctx.nodes[i].w;
    let (scale, k, tx, ty) = match fit_of(ctx, i) {
        "contain" => {
            let s = side / def.bw.max(def.bh);
            (f4(s), s, def.tx, def.ty)
        }
        "cover" => {
            let s = side / def.bw.min(def.bh);
            (f4(s), s, def.tx, def.ty)
        }
        "stretch" => {
            let sx = side / def.bw;
            let sy = side / def.bh;
            let (a, b) = (f4(sx), f4(sy));
            let st = if a == b { a } else { format!("{} {}", a, b) };
            (st, (sx * sy).sqrt(), def.tx, def.ty)
        }
        _ => {
            let s = side / 256.0;
            (f4(s), s, "-128", "-128")
        }
    };
    let fill = paint(ctx, i, "fill");
    let stroke = paint(ctx, i, "stroke");
    let sw = ctx.comp[i].stroke_width / k;
    let mut v = Vec::new();
    v.push(format!("<g transform=\"scale({}) translate({} {})\">", scale, tx, ty));
    if fill != "none" && !def.body.is_empty() {
        v.push(format!("  <g fill=\"{}\" stroke=\"none\">", fill));
        for e in &def.body {
            v.push(format!("    {}", e));
        }
        v.push("  </g>".to_string());
    }
    if !def.line.is_empty() {
        v.push(format!(
            "  <g fill=\"none\" stroke=\"{}\" stroke-width=\"{}\" stroke-linecap=\"round\" stroke-linejoin=\"round\">",
            stroke,
            f4(sw)
        ));
        for e in &def.line {
            v.push(format!("    {}", e));
        }
        v.push("  </g>".to_string());
    }
    if !def.dots.is_empty() {
        v.push(format!("  <g fill=\"{}\" stroke=\"none\">", stroke));
        for e in &def.dots {
            v.push(format!("    {}", e));
        }
        v.push("  </g>".to_string());
    }
    v.push("</g>".to_string());
    v
}

// `|image|`: a raster or SVG file, embedded.
//
// `src:` is an http(s) URL or data: URI (referenced as is) or a local path,
// read relative to the input file's directory. Rasters (sniffed by magic:
// PNG, JPEG, GIF, WebP) embed as a base64 data: URI in an `<image>`; an SVG
// file is inlined as a nested `<svg>` with its ids namespaced. `fit` maps to
// preserveAspectRatio (contain/auto: the default meet, cover: slice,
// stretch: none).

use crate::ast::Term;
use crate::compile::Ctx;
use crate::diag::Diag;
use crate::scene::{Node, SheetModel};
use crate::style::single_term;
use crate::util::{base64, f4, hash8, xml_escape};
use std::path::{Path, PathBuf};

pub enum Payload {
    Href(String),
    Svg(String),
}

pub fn is_url(s: &str) -> bool {
    let l = s.to_ascii_lowercase();
    l.starts_with("http://") || l.starts_with("https://") || l.starts_with("data:")
}

pub fn resolve_path(file: &str, src: &str) -> PathBuf {
    let base = Path::new(file).parent().unwrap_or(Path::new(""));
    base.join(src)
}

fn sniff(bytes: &[u8]) -> Option<&'static str> {
    if bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
        Some("image/png")
    } else if bytes.starts_with(b"\xff\xd8\xff") {
        Some("image/jpeg")
    } else if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
        Some("image/gif")
    } else if bytes.len() >= 12 && &bytes[0..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        Some("image/webp")
    } else {
        None
    }
}

// Read and classify a local image. Err carries the reason after the dash.
pub fn load(path: &Path) -> Result<Payload, String> {
    let bytes = match std::fs::read(path) {
        Ok(b) => b,
        Err(e) => {
            if e.kind() == std::io::ErrorKind::NotFound {
                return Err("no such file".to_string());
            }
            return Err(e.to_string());
        }
    };
    if let Some(mime) = sniff(&bytes) {
        return Ok(Payload::Href(format!("data:{};base64,{}", mime, base64(&bytes))));
    }
    if let Ok(text) = std::str::from_utf8(&bytes) {
        if svg_root(text).is_some() {
            return Ok(Payload::Svg(text.to_string()));
        }
    }
    Err("not an SVG or raster (PNG/JPEG/GIF/WebP)".to_string())
}

// Resolve-time check of `src:` (and the read itself).
pub fn check_src(sheet: &SheetModel, n: &Node, file: &str, opts: &crate::Options) -> Result<(), Diag> {
    let d = match crate::icon::winning_decl(sheet, n, "src") {
        Some(d) => d,
        None => return Ok(()),
    };
    let s = match single_term(&d.value) {
        Some(Term::Str(s, _)) => s.clone(),
        Some(Term::Ident(..)) => {
            return Err(Diag::error("resolve", "'src' takes a quoted string — write src: \"…\"", d.span));
        }
        _ => return Ok(()),
    };
    if is_url(&s) {
        return Ok(());
    }
    if opts.no_fs {
        return Err(Diag::error(
            "asset-no-fs",
            &format!("cannot read image '{}' — local files are off (--no-fs); use an http(s) URL or a data: URI", s),
            d.span,
        ));
    }
    match load(&resolve_path(file, &s)) {
        Ok(_) => Ok(()),
        Err(why) => Err(Diag::error("asset-not-found", &format!("cannot read image '{}' — {}", s, why), d.span)),
    }
}

// Before layout: a childless image needs both sides.
pub fn check_sizes(ctx: &Ctx) -> Result<(), Diag> {
    for (i, n) in ctx.nodes.iter().enumerate() {
        if n.prim == crate::types::Prim::Image && n.children.is_empty() {
            let c = &ctx.comp[i];
            if c.width.is_none() || c.height.is_none() {
                return Err(Diag::error("missing-required-property", "'|image|' requires 'width' and 'height'", n.span));
            }
        }
    }
    Ok(())
}

fn src_of(ctx: &Ctx, i: usize) -> Option<String> {
    match ctx.nodes[i].props.get("src").and_then(single_term) {
        Some(Term::Str(s, _)) => Some(s.clone()),
        _ => None,
    }
}

// The image element (unindented; an inlined SVG's content is emitted raw,
// its closing tag as the last line).
pub fn shape_lines(ctx: &Ctx, i: usize) -> Vec<String> {
    let src = match src_of(ctx, i) {
        Some(s) => s,
        None => return vec![],
    };
    let payload = if is_url(&src) {
        Payload::Href(src.clone())
    } else {
        match load(&resolve_path(&ctx.file, &src)) {
            Ok(p) => p,
            Err(_) => return vec![],
        }
    };
    let (w, h) = (ctx.nodes[i].w, ctx.nodes[i].h);
    let par = match crate::icon::fit_of(ctx, i) {
        "cover" => " preserveAspectRatio=\"xMidYMid slice\"",
        "stretch" => " preserveAspectRatio=\"none\"",
        _ => "",
    };
    let geo = format!("x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"", f4(-w / 2.0), f4(-h / 2.0), f4(w), f4(h));
    match payload {
        Payload::Href(href) => vec![format!("<image href=\"{}\" {}{}/>", xml_escape(&href), geo, par)],
        Payload::Svg(text) => inline_svg(&text, &geo, par),
    }
}

// ------------------------------------------------------------------ SVG

struct Attr {
    name: String,
    value: String, // raw text between the quotes
}

struct Root {
    attrs: Vec<Attr>,
    inner: String,
}

fn skip_ws(s: &str, mut i: usize) -> usize {
    let b = s.as_bytes();
    while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n' || b[i] == b'\r') {
        i += 1;
    }
    i
}

// Parse the document down to its root `<svg>`: prolog, attributes, content.
fn svg_root(text: &str) -> Option<Root> {
    let s = text.strip_prefix('\u{feff}').unwrap_or(text);
    let mut i = 0;
    loop {
        i = skip_ws(s, i);
        let rest = &s[i..];
        if rest.starts_with("<?") {
            i += rest.find("?>")? + 2;
        } else if rest.starts_with("<!--") {
            i += rest.find("-->")? + 3;
        } else if rest.starts_with("<!") {
            // DOCTYPE, possibly with an internal subset
            let b = rest.as_bytes();
            let mut k = 2;
            let mut depth = 0;
            loop {
                if k >= b.len() {
                    return None;
                }
                match b[k] {
                    b'[' => depth += 1,
                    b']' => depth -= 1,
                    b'>' if depth <= 0 => break,
                    _ => {}
                }
                k += 1;
            }
            i += k + 1;
        } else {
            break;
        }
    }
    let rest = &s[i..];
    if !rest.starts_with("<svg") {
        return None;
    }
    let after = rest.as_bytes().get(4).copied();
    if !matches!(after, Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') | Some(b'>') | Some(b'/')) {
        return None;
    }
    let b = rest.as_bytes();
    let mut k = 4;
    let mut attrs = Vec::new();
    let self_closing;
    loop {
        k = skip_ws(rest, k);
        if k >= b.len() {
            return None;
        }
        if b[k] == b'>' {
            self_closing = false;
            k += 1;
            break;
        }
        if b[k] == b'/' && b.get(k + 1) == Some(&b'>') {
            self_closing = true;
            k += 2;
            break;
        }
        let ns = k;
        while k < b.len() && !matches!(b[k], b'=' | b' ' | b'\t' | b'\n' | b'\r' | b'>' | b'/') {
            k += 1;
        }
        let name = rest[ns..k].to_string();
        if name.is_empty() {
            k += 1;
            continue;
        }
        k = skip_ws(rest, k);
        let mut value = String::new();
        if k < b.len() && b[k] == b'=' {
            k = skip_ws(rest, k + 1);
            if k < b.len() && (b[k] == b'"' || b[k] == b'\'') {
                let q = b[k];
                let vs = k + 1;
                let mut e = vs;
                while e < b.len() && b[e] != q {
                    e += 1;
                }
                if e >= b.len() {
                    return None;
                }
                value = rest[vs..e].to_string();
                k = e + 1;
            } else {
                let vs = k;
                while k < b.len() && !matches!(b[k], b' ' | b'\t' | b'\n' | b'\r' | b'>') {
                    k += 1;
                }
                value = rest[vs..k].to_string();
            }
        }
        attrs.push(Attr { name, value });
    }
    let inner = if self_closing {
        String::new()
    } else {
        let body = &rest[k..];
        match body.rfind("</svg>") {
            Some(e) => body[..e].to_string(),
            None => body.to_string(),
        }
    };
    Some(Root { attrs, inner })
}

// A width/height usable for a synthesised viewBox: a plain number, optionally in px.
fn plain_len(v: &str) -> Option<String> {
    let t = v.trim();
    let t = t.strip_suffix("px").unwrap_or(t);
    if t.parse::<f64>().is_ok() && !t.is_empty() && !t.contains(|c: char| c.is_alphabetic()) {
        Some(t.to_string())
    } else {
        None
    }
}

fn attr_out(name: &str, value: &str) -> String {
    format!(" {}=\"{}\"", name, value.replace('"', "&quot;"))
}

// Rewrite `url(#id)` references to defined ids.
fn rewrite_urls(s: &str, ids: &[String], prefix: &str) -> String {
    let mut out = String::new();
    let mut rest = s;
    while let Some(p) = rest.find("url(") {
        out.push_str(&rest[..p + 4]);
        rest = &rest[p + 4..];
        let end = rest.find(')').unwrap_or(rest.len());
        let inner = &rest[..end];
        let lead = inner.len() - inner.trim_start_matches(|c: char| c == ' ' || c == '"' || c == '\'').len();
        let core = inner.trim_matches(|c: char| c == ' ' || c == '"' || c == '\'');
        if let Some(id) = core.strip_prefix('#') {
            if ids.iter().any(|x| x == id) {
                out.push_str(&inner[..lead]);
                out.push('#');
                out.push_str(prefix);
                out.push_str(id);
                out.push_str(&inner[lead + core.len()..]);
                rest = &rest[end..];
                continue;
            }
        }
        out.push_str(inner);
        rest = &rest[end..];
    }
    out.push_str(rest);
    out
}

fn rewrite_attr(name: &str, value: &str, ids: &[String], prefix: &str) -> String {
    if name == "id" {
        return format!("{}{}", prefix, value);
    }
    if name == "href" || name == "xlink:href" {
        if let Some(id) = value.strip_prefix('#') {
            if ids.iter().any(|x| x == id) {
                return format!("#{}{}", prefix, id);
            }
        }
    }
    rewrite_urls(value, ids, prefix)
}

// Collect every `id="…"` attribute in the content (outside comments).
fn collect_ids(content: &str, ids: &mut Vec<String>) {
    scan(content, &mut |tok: Tok| {
        if let Tok::Attr(name, value, _) = tok {
            if name == "id" {
                ids.push(value.to_string());
            }
        }
    });
}

enum Tok<'a> {
    Raw(&'a str),               // markup copied as is (tag names, comments, spacing)
    Text(&'a str),              // character data (and CDATA)
    Attr(&'a str, &'a str, u8), // attribute name, raw value, quote byte (0 = unquoted)
}

// A small XML scanner: splits content into raw markup, text and attribute values.
fn scan<'a>(s: &'a str, f: &mut dyn FnMut(Tok<'a>)) {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if s[i..].starts_with("<!--") {
            let e = s[i..].find("-->").map(|p| i + p + 3).unwrap_or(b.len());
            f(Tok::Raw(&s[i..e]));
            i = e;
        } else if s[i..].starts_with("<![CDATA[") {
            f(Tok::Raw(&s[i..i + 9]));
            let e = s[i + 9..].find("]]>").map(|p| i + 9 + p).unwrap_or(b.len());
            f(Tok::Text(&s[i + 9..e]));
            let e2 = (e + 3).min(b.len());
            f(Tok::Raw(&s[e..e2]));
            i = e2;
        } else if b[i] == b'<' && (s[i..].starts_with("<?") || s[i..].starts_with("<!") || s[i..].starts_with("</")) {
            let e = s[i..].find('>').map(|p| i + p + 1).unwrap_or(b.len());
            f(Tok::Raw(&s[i..e]));
            i = e;
        } else if b[i] == b'<' {
            // start tag: name, then attributes
            let mut k = i + 1;
            while k < b.len() && !matches!(b[k], b' ' | b'\t' | b'\n' | b'\r' | b'>' | b'/') {
                k += 1;
            }
            f(Tok::Raw(&s[i..k]));
            loop {
                let ws = k;
                k = skip_ws(s, k);
                if k > ws {
                    f(Tok::Raw(&s[ws..k]));
                }
                if k >= b.len() {
                    break;
                }
                if b[k] == b'>' {
                    f(Tok::Raw(">"));
                    k += 1;
                    break;
                }
                if b[k] == b'/' {
                    f(Tok::Raw("/"));
                    k += 1;
                    continue;
                }
                let ns = k;
                while k < b.len() && !matches!(b[k], b'=' | b' ' | b'\t' | b'\n' | b'\r' | b'>' | b'/') {
                    k += 1;
                }
                let name = &s[ns..k];
                if name.is_empty() {
                    f(Tok::Raw(&s[k..k + 1]));
                    k += 1;
                    continue;
                }
                let mut j = skip_ws(s, k);
                if j < b.len() && b[j] == b'=' {
                    j = skip_ws(s, j + 1);
                    if j < b.len() && (b[j] == b'"' || b[j] == b'\'') {
                        let q = b[j];
                        let mut e = j + 1;
                        while e < b.len() && b[e] != q {
                            e += 1;
                        }
                        // name and everything up to the opening quote stay raw
                        f(Tok::Raw(&s[ns..j + 1]));
                        f(Tok::Attr(name, &s[j + 1..e.min(b.len())], q));
                        let e2 = (e + 1).min(b.len());
                        f(Tok::Raw(&s[e.min(b.len())..e2]));
                        k = e2;
                        continue;
                    }
                }
                f(Tok::Raw(&s[ns..k]));
            }
            i = k;
        } else {
            let e = s[i..].find('<').map(|p| i + p).unwrap_or(b.len());
            f(Tok::Text(&s[i..e]));
            i = e;
        }
    }
}

fn inline_svg(text: &str, geo: &str, par: &str) -> Vec<String> {
    let root = match svg_root(text) {
        Some(r) => r,
        None => return vec![],
    };
    let prefix = format!("lini-a{}-", hash8(text));
    let mut ids: Vec<String> = root.attrs.iter().filter(|a| a.name == "id").map(|a| a.value.clone()).collect();
    collect_ids(&root.inner, &mut ids);
    let mut head = format!("<svg {}{}", geo, par);
    let has_vb = root.attrs.iter().any(|a| a.name == "viewBox");
    if !has_vb {
        let w = root.attrs.iter().find(|a| a.name == "width").and_then(|a| plain_len(&a.value));
        let h = root.attrs.iter().find(|a| a.name == "height").and_then(|a| plain_len(&a.value));
        if let (Some(w), Some(h)) = (w, h) {
            head.push_str(&format!(" viewBox=\"0 0 {} {}\"", w, h));
        }
    }
    for a in &root.attrs {
        if matches!(a.name.as_str(), "xmlns" | "width" | "height" | "x" | "y" | "preserveAspectRatio") {
            continue;
        }
        head.push_str(&attr_out(&a.name, &rewrite_attr(&a.name, &a.value, &ids, &prefix)));
    }
    head.push('>');
    let mut body = String::new();
    scan(&root.inner, &mut |tok: Tok| match tok {
        Tok::Raw(r) => body.push_str(r),
        Tok::Text(t) => body.push_str(&rewrite_urls(t, &ids, &prefix)),
        Tok::Attr(name, value, _) => body.push_str(&rewrite_attr(name, value, &ids, &prefix)),
    });
    let body = body.trim_matches('\n');
    if body.is_empty() {
        vec![head, "</svg>".to_string()]
    } else {
        vec![format!("{}\n{}", head, body), "</svg>".to_string()]
    }
}

