#!/usr/bin/env python3
# usage: nodecmp.py file.lini [args] -> compare every lini-icon / lini-image node block (ignoring its transform)
import subprocess, sys, os, re
f = sys.argv[1]
args = sys.argv[2:]
d = os.path.dirname(os.path.abspath(f)); b = os.path.basename(f)
def run(exe):
    r = subprocess.run([exe] + args + [b], capture_output=True, cwd=d)
    return r.stdout.decode()
def blocks(o):
    lines = o.split('\n')
    out = []
    i = 0
    while i < len(lines):
        l = lines[i]
        if re.search(r'class="lini-node[^"]*lini-(icon|image)', l):
            ind = len(l) - len(l.lstrip())
            blk = [re.sub(r' transform="translate\([^)]*\)', '', l.strip())]
            i += 1
            while i < len(lines) and not (lines[i].startswith(' ' * ind + '</g>') and len(lines[i]) - len(lines[i].lstrip()) == ind):
                blk.append(lines[i][ind:])
                i += 1
            out.append('\n'.join(blk))
        i += 1
    return out
b1 = blocks(run('/workspace/executable')); b2 = blocks(run('/tmp/bin-icon/executable'))
print('blocks', len(b1), len(b2))
bad = 0
for k, (x, y) in enumerate(zip(b1, b2)):
    if x != y:
        bad += 1
        if bad <= 3:
            print('--- block', k)
            xl, yl = x.split('\n'), y.split('\n')
            for a, c in zip(xl, yl):
                if a != c:
                    print('<', a[:200]); print('>', c[:200])
print('differing blocks', bad)

