#!/usr/bin/env python3
# Compare "unknown icon" suggestions between the original and ours on random probes.
import random, subprocess, sys
from concurrent.futures import ThreadPoolExecutor
names = open('/tmp/icon/disc/valid.txt').read().split()
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
ALPHA = 'abcdefghijklmnopqrstuvwxyz-'
def mutate(s):
    k = random.randint(1, 3)
    for _ in range(k):
        op = random.randint(0, 2)
        i = random.randint(0, len(s))
        if op == 0 and len(s) > 1:
            i = min(i, len(s) - 1); s = s[:i] + s[i + 1:]
        elif op == 1:
            s = s[:i] + random.choice(ALPHA) + s[i:]
        else:
            i = min(i, len(s) - 1); s = s[:i] + random.choice(ALPHA) + s[i + 1:]
    return s
probes = set()
while len(probes) < 4000:
    if random.random() < 0.15:
        probes.add(''.join(random.choice(ALPHA[:-1]) for _ in range(random.randint(0, 5))))
    else:
        probes.add(mutate(random.choice(names)))
probes = sorted(probes)
def run(exe, p):
    r = subprocess.run([exe, '-'], input=('|icon| { symbol: "%s" }' % p).encode(), capture_output=True)
    return r.stderr.decode(), r.returncode
def both(p):
    return p, run('/workspace/executable', p), run('/tmp/bin-icon/executable', p)
bad = 0
with ThreadPoolExecutor(16) as ex:
    for p, a, b in ex.map(both, probes):
        if a != b:
            bad += 1
            if bad < 10:
                print(repr(p), a, b)
print('probes', len(probes), 'mismatches', bad)

